-- School profile (general details, address, logo) and saved custom reports.
CREATE TABLE public.school_profile (institution_id UUID PRIMARY KEY REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL DEFAULT '', short_name VARCHAR(20) NOT NULL DEFAULT '', board VARCHAR(40) NOT NULL DEFAULT '', affiliation_no VARCHAR(40) NOT NULL DEFAULT '', udise_code VARCHAR(20) NOT NULL DEFAULT '', year_established INTEGER CHECK (year_established BETWEEN 1800 AND 2100), principal VARCHAR(80) NOT NULL DEFAULT '', email VARCHAR(120) NOT NULL DEFAULT '', phone VARCHAR(30) NOT NULL DEFAULT '', website VARCHAR(160) NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', city VARCHAR(60) NOT NULL DEFAULT '', state VARCHAR(60) NOT NULL DEFAULT '', pin_code VARCHAR(10) NOT NULL DEFAULT '', map_link VARCHAR(300) NOT NULL DEFAULT '', logo TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.saved_reports (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(100) NOT NULL, dataset VARCHAR(20) NOT NULL, columns TEXT NOT NULL, filter_value VARCHAR(60) NOT NULL DEFAULT '', group_by VARCHAR(40) NOT NULL DEFAULT '', created_by VARCHAR(80) NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (institution_id, name));
ALTER TABLE public.school_profile ENABLE ROW LEVEL SECURITY; ALTER TABLE public.saved_reports ENABLE ROW LEVEL SECURITY;
